import{canonicalSourceSlot,composeAgentModuleCandidates}from"#compiler/source-graph.js";import{deriveMemorySlot}from"#compiler/normalize-definitions.js";import{scheduleCollectionToolPrefix}from"#shared/schedule-collection-tools.js";function applyAgentToolPolicy(e,t){t.tool!==!1||e.graph.orderedCandidates.some(e=>e.layer!==`framework-default`&&canonicalSourceSlot(e.logicalPath)===`tools/agent`)||(e.graph.composed=composeAgentModuleCandidates(e.graph.orderedCandidates.filter(e=>e.layer!==`framework-default`||canonicalSourceSlot(e.logicalPath)!==`tools/agent`)))}function canDisableToolWithoutSelectedSource(e,t){return e.projected.subagents.some(e=>e.source.subagentId===t)||e.orderedCandidates.some(e=>e.backing.kind!==`resource`&&featureToolName(e.logicalPath)===t)}function featureToolName(e){let t=canonicalSourceSlot(e);if(t===`memory`||t.startsWith(`memory/`))return deriveMemorySlot(e);if(t.startsWith(`schedules/`))return scheduleCollectionToolPrefix(t.slice(10))}function applyDefaultToolPolicy(e,t){if(t.defaultTools!==!1)return;let n=new Set(e.graph.orderedCandidates.filter(e=>e.layer!==`framework-default`).map(e=>canonicalSourceSlot(e.logicalPath)));e.graph.composed=composeAgentModuleCandidates(e.graph.orderedCandidates.filter(e=>{let t=canonicalSourceSlot(e.logicalPath);return e.layer!==`framework-default`||!t.startsWith(`tools/`)||n.has(t)}))}export{applyAgentToolPolicy,applyDefaultToolPolicy,canDisableToolWithoutSelectedSource};